import { zhArticles, site, type Article } from './articles';

/**
 * Real site content for the Growlio landing page.
 *
 * Every string/number here is derived from data/articles.json
 * (generated by scripts/prebuild.js from the real markdown posts).
 * Nothing is invented: categories come from each post's explicit
 * `category:` frontmatter field (keyword rules only as fallback),
 * counts are computed from the manifest, and summaries are the posts'
 * own "一句话导读" sentence.
 */

export interface Category {
  key: string;
  name: string;
  /** short topic label used in pills / card logo slots (<=6 chars) */
  label: string;
  /** keyword rule over title+slug — real posts only */
  match: RegExp;
}

