export const zh = zhArticles();

/**
 * All zh posts in the category, newest first.
 * The manifest `category` field (explicit frontmatter, backfilled for all
 * 179 stock posts in P0) is authoritative, so the six categories partition
 * the site: sum of counts == total. The keyword rule only covers posts
 * whose manifest field is missing (e.g. a stale data/articles.json).
 */
export function postsInCategory(key: string): Article[] {
  const cat = CATEGORIES.find((c) => c.key === key);
  if (!cat) return [];
  return zh.filter((a) =>
    a.category ? a.category === key : cat.match.test(a.title) || cat.match.test(a.slug),
  );
}

export function categoryCount(key: string): number {
  return postsInCategory(key).length;
}

export function newestInCategory(key: string): Article | undefined {
  return postsInCategory(key)[0];
}

export function categoryOf(a: Article): Category | undefined {
  if (a.category) return CATEGORIES.find((c) => c.key === a.category);
  return CATEGORIES.find(
    (c) => c.match.test(a.title) || c.match.test(a.slug),
  );
}

/** Zh posts with no category at all (manifest field missing AND no rule
 *  match). Should be empty after the P0 backfill; listed in the build
 *  log by scripts/prebuild.js when non-empty. */
export function uncategorizedPosts(): Article[] {
  return zh.filter((a) => !categoryOf(a));
}

/**
 * Short topic label for nav pills / small card slots.
 * One of the six category names when the post matches, else an
 * honest label derived from the post's own title keywords.
 */
export function topicLabel(a: Article): string {
  const cat = categoryOf(a);
  if (cat) return cat.label;
  if (/建站|Pages/i.test(a.title)) return '免费建站';
  if (/VPN|WARP|Proton/i.test(a.title)) return '免费VPN';
  if (/CDN/i.test(a.title)) return '免费CDN';
  if (/转运|收货地址/i.test(a.title)) return '转运地址';
  if (/Tunnel/i.test(a.title)) return '免费隧道';
  if (/推特|私域/i.test(a.title)) return '推特引流';
  if (/独立站/i.test(a.title)) return '跨境独立站';
  if (/资源大集合/i.test(a.title)) return '资源大集合';
  return '实测教程';
}

/** The post's own one-line summary (its 一句话导读 sentence). */
export function oneLineSummary(a: Article, maxLen = 60): string {
  const m = a.excerpt.match(/一句话导读\s*[：:]\s*([^。]+。)/);
  if (m) {
    let s = m[1].trim();
    if (s.length > maxLen) s = s.slice(0, maxLen - 1) + '…';
    return s;
  }
  // fallback: plain excerpt head (real text, just trimmed)
  const s = a.excerpt.replace(/\s+/g, ' ').trim();
  return s.length > maxLen ? s.slice(0, maxLen - 1) + '…' : s;
}

const allArticles: Article[] = site.articles;
const sortedDates = [...new Set(allArticles.map((a) => a.date))].sort();
const firstDate = sortedDates[0];
const lastDate = sortedDates[sortedDates.length - 1];

export const STATS = {
  total: allArticles.length,
  zh: zh.length,
  en: allArticles.length - zh.length,
  categories: CATEGORIES.length,
  // first publish date → latest publish date, inclusive
  days:
    Math.round((Date.parse(lastDate) - Date.parse(firstDate)) / 86400000) + 1,
  firstDate,
  lastDate,
};

/** Every publish date (oldest → newest) with the cumulative post count. */
export const CUMULATIVE_SERIES: { date: string; total: number }[] = (() => {
  let run = 0;
  return sortedDates.map((date) => {
    run += allArticles.filter((a) => a.date === date).length;
    return { date, total: run };
  });
})();

/** Posts per weekday (Mon..Sun) across all articles. */
export const WEEKDAY_COUNTS: number[] = (() => {
  const counts = [0, 0, 0, 0, 0, 0, 0];
  for (const a of allArticles) {
    const dow = new Date(`${a.date}T12:00:00Z`).getUTCDay(); // 0=Sun..6=Sat
    counts[(dow + 6) % 7] += 1;
  }
  return counts;
})();

